    if (path === "admin/menu") return () => renderAdminMenu(ctx());
    if (path === "admin/orders") return () => renderAdminOrders(ctx());
    if (path === "admin/reviews") return () => renderAdminReviews(ctx());
    if (path === "admin/counters") return () => renderAdminCounters(ctx());
